(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[160],{3290:(e,a,i)=>{Promise.resolve().then(i.bind(i,1995)),Promise.resolve().then(i.bind(i,9478)),Promise.resolve().then(i.bind(i,8086)),Promise.resolve().then(i.bind(i,3719)),Promise.resolve().then(i.bind(i,8438))},8438:(e,a,i)=>{"use strict";i.d(a,{Providers:()=>c});var n=i(5155),r=i(2200),l=i(7985),t=i(4431),s=i(1218);let o=JSON.parse('{"header":{"callUs":"Call Us","getDirections":"Get Directions","projectCatalog":"project catalog","navigation":{"hebilblue":"Hebilblue","project":"project","sitePlan":"site plan","amenities":"amenities","gallery":"gallery","hotel":"hotel","contact":"contact"}},"hero":{"title":"Rebirth with Aegean Breezes","description":"In Bodrum\'s blue-flagged Hebil Bay, just steps from the sea; a new life experience embracing all the colors of nature. This prestigious project, consisting of 80 modern structures, each with its own private pool, offers a unique lifestyle with its commanding position over the Aegean blue, panoramic sea view, and private pier. Surrounded by olive trees and pine forests, Hebil Bay offers a privileged living space with its location adjacent to Paradise Bay\'s clarity, while promising tranquility close to T\xfcrkb\xfck\xfc\'s social life but far from the crowds. Hebil Blue is designed for those who want to experience Bodrum in all four seasons and redefine life.","description_short":"A prestigious project consisting of 80 modern structures in Bodrum Hebil Bay, just steps from the sea. It offers a unique lifestyle with its commanding position over the Aegean blue and private pier. A peaceful environment close to social life but immersed in nature."},"banner":{"title":"hebil blue hotel","description":"A different life awaits you in Hebil, one of Bodrum\'s bays crowned with blue, just a few steps away from the sea. With its modern architecture, natural materials and timeless aesthetics, Hebil Blue redefines life with its understated luxury approach, sustainable living solutions and privileged location."},"banner_2":{"title":"hebil blue hotel","description":"Silence, Elegance and a World-Class Living Experience The unique nature and architecture of Hebil Blue will soon be crowned with the signature of a world-renowned prestigious brand. Standing out with its flawless service understanding, sophisticated design, and timeless luxury, this brand will offer a prestigious destination designed for privileged guests in Bodrum\'s most special bay. The countdown has begun for this exclusive living experience."},"verandalar":"VERANDAS, FIRE PITS AND INNER GARDENS...","verandalar_description":"Spacious and airy verandas, stylish fire pits, and carefully crafted inner gardens are designed to make every moment special and add aesthetic value to your life.\\nWhile every detail inspires you to collect memories that will be etched in your mind, the landscape shaped with imported plants offers refined naturalness. The advanced technology lighting systems that elegantly envelop the night perfectly complete the magic of the atmosphere.","zamansiz_mimari_description":"Every detail in Hebil Blue is designed to provide the highest level of elegance and comfort. Spacious verandas opening to panoramic views, special seating areas enriched with fire pits, and inner gardens integrated with landscaping add value to every moment and aesthetics to every glance. These unique living spaces immersed in nature come together with the clean lines of modern architecture and premium material selection, offering a new definition of privilege. Each of the 80 modern structures is equipped with its own pool, private garden, and living spaces that create a fascinating atmosphere at every hour of the day.","kullanim_alani_description_1":"Hebil Blue is designed to suit different lifestyle preferences. ","kullanim_alani_description_2":"42 Type A units offer wider and more versatile living spaces with 6+1 and 5+2 options, while 38 Type B units offer comfort and functionality together with a 5+1 plan. Each structure is equipped with its private garden, pool, and spacious verandas, as well as refined details and high-quality materials.","kullanim_alani_description_3":"Type A has a total of 3 parking spaces, 2 covered and 1 open, while Type B has 1 covered and 1 open parking space.","kullanim_alani_description_4":"This way, a perfect living space is offered not only visually but also functionally.","doga_description_1":"Hebil Blue is not just a living space; it offers a special living experience with every detail thought out, providing enjoyment in all four seasons. You can start your day with a peaceful walk, enjoy the sea at your private pier, then relax at the spa center.","doga_description_2":"Restaurant & Snack Bar. Fitness & Spa Areas, Walking Trails & Children\'s Playgrounds, Electric Vehicle Charging Stations, Covered and Open Parking, Buggy Service, Gardening & Cleaning Services, Seawater Desalination System, Hotel Comfort Service, 24/7 Security.","timeless_architecture":"Timeless Architecture, Unique Living Spaces","stats":{"modern_buildings":"MODERN BUILDINGS","project_area":"PROJECT AREA","pier":"PIER","units":"units","square_meters":"m\xb2"},"lifestyle_areas":"LIVING SPACES SUITABLE FOR YOUR NEEDS","comfort_nature":"Comfort in every moment of life, privilege immersed in nature…","city_dynamics":"CLOSE TO CITY DYNAMICS, IN THE HEART OF NATURE.","project_images":"Project Images","location":{"title":"LOCATION","subtitle":"Hebil Bay / T\xfcrkb\xfck\xfc","description":"Close to Tranquility, Yet in the Heart of Life! While located in a peaceful atmosphere immersed in nature; you are just minutes away from Bodrum\'s most popular spots. Go down to the beach at any time of day you wish, go shopping at Yalıkavak Marina… All just a road away!"},"contact":{"title":"Call Us","description":"Fill out the form to discover your dream home on site and learn about project-specific privileges; our lifestyle consultants will call you. If you wish, we would be happy to host you at our sales office."},"footer":{"copyright":"Copyright \xa9 2025 HEBILBLUE All rights reserved.","office":"Hebil Blue Sales Office","address":"T\xfcrkb\xfck\xfc Mah. Hebil Cad. 156 Sk. Bodrum/MUĞLA","phone":"+90 532 635 56 62"},"locations":{"turkbuku":"t\xfcrkb\xfck\xfc","gundogan":"g\xfcndoğan","cennet_koyu":"paradise bay","yalikavak":"yalıkavak","airport":"airport"}}'),d=JSON.parse('{"header":{"callUs":"Sizi arayalım","getDirections":"Yol Tarifi Al","projectCatalog":"proje kataloğu","navigation":{"hebilblue":"Hebilblue","project":"proje","sitePlan":"vaziyet planı","amenities":"olanaklar","gallery":"galeri","hotel":"hotel","contact":"iletisim"}},"hero":{"title":"Ege Esintileriyle Yeniden Doğuş","description":"Bodrum\'un mavi bayraklı Hebil Koyu\'nda, denize adım mesafede; doğanın t\xfcm renklerini i\xe7ine alan yeni bir yaşam deneyimi. Her biri \xf6zel havuzlu 80 modern yapıdan oluşan bu se\xe7kin proje, Ege\'nin maviliğine h\xe2kim konumu, panoramik deniz manzarası ve \xf6zel iskelesiyle benzersiz bir yaşam sunuyor. Zeytin ağa\xe7ları ve \xe7am ormanlarıyla \xe7evrili Hebil Koyu, Cennet Koy\'un berraklığına komşu konumuyla ayrıcalıklı bir yaşam alanı sunarken, T\xfcrkb\xfck\xfc\'n\xfcn sosyal yaşamına yakın, kalabalıktan ise uzak bir huzur vadediyor. Hebil Blue, d\xf6rt mevsim Bodrum\'u yaşamak ve hayatı yeniden tanımlamak isteyenler i\xe7in tasarlandı.","description_short":"Bodrum Hebil Koyu\'nda, denize adım mesafede 80 modern yapıdan oluşan se\xe7kin proje. Ege\'nin maviliğine h\xe2kim konumu ve \xf6zel iskelesiyle benzersiz bir yaşam sunuyor. Doğayla i\xe7 i\xe7e, sosyal yaşama yakın ama huzurlu bir ortam."},"banner":{"title":"hebil blue hotel","description":"Bodrum’un maviyle ta\xe7lanmış koylarından Hebil’de, denize sadece birka\xe7 adım uzaklıkta bambaşka bir yaşam sizi bekliyor. Modern mimarisi, doğal malzemeleri ve zamansız estetiğiyle Hebil Blue; sade l\xfcks anlayışı, s\xfcrd\xfcr\xfclebilir yaşam \xe7\xf6z\xfcmleri ve ayrıcalıklı konumuyla hayatı yeniden tanımlıyor."},"banner_2":{"title":"hebil blue hotel","description":"Sessizlik, Zarafet ve D\xfcnya Standartlarında Bir Yaşam Deneyimi Hebil Blue\'nun benzersiz doğası ve mimarisi, \xe7ok yakında d\xfcnya \xe7apında tanınan se\xe7kin bir markanın imzasıyla ta\xe7lanıyor. Kusursuz hizmet anlayışı, sofistike tasarımı ve zamansız l\xfcks\xfcyle \xf6ne \xe7ıkan bu marka; Bodrum\'un en \xf6zel koyunda, ayrıcalıklı misafirler i\xe7in tasarlanmış prestijli bir destinasyon sunacak. Bu se\xe7kin yaşam deneyimi i\xe7in geri sayım başladı."},"verandalar":"VERANDALAR, ATEŞ \xc7UKURLARI VE İ\xc7 BAH\xc7ELER...","verandalar_description":"Geniş ve ferah verandalar, stil sahibi ateş \xe7ukurları ve \xf6zenle kurgulanmış i\xe7 bah\xe7eler; her anı \xf6zel kılmak ve yaşamınıza estetik bir değer katmak i\xe7in tasarlandı.\\nHer detay, hafızalara kazınacak anılar biriktirmeniz i\xe7in ilham verirken; ithal bitkilerle şekillenen peyzaj, rafine bir doğallık sunar. Geceyi zarafetle saran ileri teknoloji ışık sistemleri ise, ortamın b\xfcy\xfcs\xfcn\xfc kusursuzca tamamlar.","zamansiz_mimari_description":"Hebil Blue\'da her detay, zarafet ve konforu en y\xfcksek d\xfczeyde yaşatmak \xfczere kurgulandı. Panoramik manzaraya a\xe7ılan geniş verandalar, ateş \xe7ukurlarıyla zenginleştirilmiş \xf6zel oturma alanları ve peyzajla b\xfct\xfcnleşen i\xe7 bah\xe7eler; her anınıza değer, her bakışınıza estetik katıyor. Doğayla i\xe7 i\xe7e bu benzersiz yaşam alanları; modern mimarinin yalın \xe7izgileri ve \xfcst segment malzeme se\xe7imiyle buluşarak, ayrıcalığın yeni tanımını sunuyor. 80 modern yapının her biri; kendine ait havuz, \xf6zel bah\xe7e ve g\xfcn\xfcn her saatinde b\xfcy\xfcleyici bir atmosfer yaratan yaşam alanlarıyla donatıldı.","kullanim_alani_description_1":"Hebil Blue, farklı yaşam tercihlerine uygun olarak tasarlandı. ","kullanim_alani_description_2":"42 adet A tipi; 6+1 ve 5+2 se\xe7enekleriyle daha geniş ve \xe7ok y\xf6nl\xfc kullanım alanları sunarken,  38 adet B tipi ise 5+1 planıyla konforu ve işlevselliği bir arada sunuyor. Her yapı, \xf6zel bah\xe7esi, havuzu ve geniş verandaların yanı sıra; incelikli detaylar ve y\xfcksek kaliteli malzemelerle donatıldı.","kullanim_alani_description_3":"A tipinde her biri 2 kapalı ve 1 a\xe7ık olmak \xfczere toplam 3 ara\xe7lık otopark alanı bulunurken,  B tipinde ise 1 kapalı ve 1 a\xe7ık otopark alanı yer alıyor.","kullanim_alani_description_4":"Bu sayede yalnızca g\xf6rsel olarak değil, fonksiyonel a\xe7ıdan da m\xfckemmel bir yaşam alanı sunuluyor.","doga_description_1":"Hebil Blue, sadece bir yaşam alanı değil; her detayı d\xfcş\xfcn\xfclm\xfcş, d\xf6rt mevsim keyif sunan \xf6zel bir yaşam deneyimi sunar. G\xfcn\xfcn\xfcze dingin bir y\xfcr\xfcy\xfcşle başlayabilir, \xf6zel iskelinizde denizin keyfini \xe7ıkarabilir, ardından spa merkezinde rahatlayabilirsiniz.","doga_description_2":"Restoran & Snack Bar. Fitness & Spa Alanları, Y\xfcr\xfcy\xfcş Parkurları & \xc7ocuk Oyun Alanları, Elektrikli Ara\xe7 Şarj İstasyonları, Kapalı ve A\xe7ık Otopark, Buggy Servis Hizmeti, Bah\xe7ıvanlık & Temizlik Hizmetleri, Deniz Suyu Desalinasyon Sistemi, Otel Konforunda Hizmet, 7/24 G\xfcvenlik.","timeless_architecture":"Zamansız Mİmarİ, eşsİz yaşam alanları","stats":{"modern_buildings":"MODERN YAPI","project_area":"PROJE ALANI","pier":"İSKELE","units":"adet","square_meters":"m\xb2"},"lifestyle_areas":"İHTİYA\xc7LARINIZA UYGUN YAŞAM ALANLARI","comfort_nature":"Hayatın her anına konfor, doğayla i\xe7 i\xe7e ayrıcalık…","city_dynamics":"ŞEHRİN DİNAMİĞİNE YAKIN, DOĞANIN KALBİNDE.","project_images":"Proje G\xf6rselleri","location":{"title":"LOKASYON","subtitle":"Hebİl Koyu / T\xfcrkb\xfck\xfc","description":"Hem Sakinliğe Yakın, Hem Hayatın İ\xe7inde! Doğayla i\xe7 i\xe7e, huzurlu bir atmosferde yer alırken; Bodrum\'un en g\xf6zde noktalarına sadece dakikalar mesafedesiniz. G\xfcn\xfcn dilediğiniz saatinde sahile inin, Yalıkavak Marina\'da alışverişe \xe7ıkın… Hepsi sadece bir yol kadar yakın!"},"contact":{"title":"Sizi Arayalım","description":"Hayalinizdeki evi yerinde keşfetmek ve projeye \xf6zel ayrıcalıkları \xf6ğrenmek i\xe7in formu doldurun; yaşam danışmanlarımız sizi arasın. Dilerseniz satış ofisimizde sizi ağırlamaktan memnuniyet duyarız."},"footer":{"copyright":"Copyright \xa9 2025 HEBILBLUE All rights reserved.","office":"Hebil Blue Satış Ofisi","address":"T\xfcrkb\xfck\xfc Mah. Hebil Cad. 156 Sk. Bodrum/MUĞLA","phone":"+90 532 635 56 62"},"locations":{"turkbuku":"t\xfcrkb\xfck\xfc","gundogan":"g\xfcndoğan","cennet_koyu":"cennet koyu","yalikavak":"yalıkavak","airport":"havaalani"}}');l.Ay.use(t.A).use(s.r9).init({resources:{tr:{translation:d},en:{translation:o}},fallbackLng:"tr",debug:!1,interpolation:{escapeValue:!1},detection:{order:["localStorage","navigator"],caches:["localStorage"]}});var u=i(9509);let m=["places","drawing","geometry"];function c(e){let{children:a}=e,{isLoaded:i,loadError:l}=(0,r.KD)({googleMapsApiKey:u.env.NEXT_PUBLIC_GOOGLE_MAP_API,libraries:m});return l?(0,n.jsx)("p",{children:"Encountered error while loading google maps"}):i?a:(0,n.jsx)("p",{children:"Map Script is loading ..."})}}},e=>{var a=a=>e(e.s=a);e.O(0,[84,212,919,211,176,441,684,358],()=>a(3290)),_N_E=e.O()}]);